const raw = $input.first().json;
const expected = $env.ANSER_WEBHOOK_TOKEN || '';
if (expected && ((raw.headers || {})['x-anser-token'] || '') !== expected) {
  return [{ json: { valid: false, error: 'Unauthorized' } }];
}
const b = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
if (!b.order_code) return [{ json: { valid: false, error: 'Missing required field: order_code' } }];
return [{ json: { valid: true, order_code: String(b.order_code) } }];

const rep = $('Get Batch Report (deterministic)').first().json;
const explain = $input.first().json.text || '';
const fmt = n => new Intl.NumberFormat('vi-VN').format(n);
// Trà/cao atiso: hao hụt sấy tươi→khô là BÌNH THƯỜNG (không báo động).
// Cảnh báo khi yield thực LỆCH quá định mức (rag tính warn_yield) hoặc NG >3%.
const warn = rep.warn_yield === true || rep.ng_pct > 3;
const report_body = JSON.stringify({ scope: 'order', ref: rep.ref, yield_actual_pct: rep.yield_actual_pct, yield_deviation_pct: rep.yield_deviation_pct, ng_pct: rep.ng_pct, cost_vnd: rep.cost_vnd, revenue_vnd: rep.revenue_vnd, profit_pct: rep.profit_pct, ai_explanation: explain });
const notify_body = JSON.stringify({ channel: 'discord', title: (warn ? '🔴' : '🟢') + ' Báo cáo SX đơn ' + rep.ref, color: warn ? 15158332 : 3066993, description: explain, fields: [ { name: 'Yield tươi→khô (thực/định mức)', value: rep.yield_actual_pct + '% / ' + rep.yield_std_pct + '%', inline: true }, { name: 'Lệch định mức', value: rep.yield_deviation_pct + '%' + (rep.warn_yield ? ' ⚠️' : ''), inline: true }, { name: 'Phế phẩm (NG)', value: rep.ng_pct + '%', inline: true }, { name: 'Sản lượng', value: rep.output_units + ' đv (' + rep.output_kg + ' kg khô / ' + rep.input_kg + ' kg tươi)', inline: true }, { name: 'Giá vốn', value: fmt(rep.cost_vnd) + ' đ', inline: true }, { name: 'Doanh thu', value: fmt(rep.revenue_vnd) + ' đ', inline: true }, { name: 'Lãi', value: rep.profit_pct + '%', inline: true } ] });
const resp = JSON.stringify({ order: rep.ref, yield_actual_pct: rep.yield_actual_pct, yield_std_pct: rep.yield_std_pct, yield_deviation_pct: rep.yield_deviation_pct, ng_pct: rep.ng_pct, profit_pct: rep.profit_pct, warn });
return [{ json: { report_body, notify_body, resp } }];
